def asn1_len(n):
    if n < 128:
        return bytes([n])
    elif n < 256:
        return bytes([0x81, n])
    else:
        return bytes([0x82, (n >> 8) & 0xff, n & 0xff])

def asn1_tlv(t, v):
    return bytes([t]) + asn1_len(len(v)) + v

def asn1_seq(v):
    return asn1_tlv(0x30, v)

def asn1_int(n):
    if n == 0:
        return asn1_tlv(0x02, b'\x00')
    b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
    if b[0] & 0x80:
        b = b'\x00' + b
    return asn1_tlv(0x02, b)

def asn1_oid(s):
    p = [int(x) for x in s.split('.')]
    r = bytes([40 * p[0] + p[1]])
    for x in p[2:]:
        if x < 128:
            r += bytes([x])
        else:
            e = []
            while x:
                e.insert(0, (x & 0x7f) | (0x80 if e else 0))
                x >>= 7
            r += bytes(e)
    return asn1_tlv(0x06, r)

